select id, product_id, sale_date, units, rank() over (order by revenue) as revenue_rank, first_value(units, true) over (partition by store_id order by sale_date, id rows between unbounded preceding and current row) as first_known_units, first_value(revenue) ignore nulls over (partition by product_id order by units, id rows between unbounded preceding and current row) as first_known_revenue, avg(revenue) over (order by revenue, id rows between 3 preceding and current row) as revenue_avg_3, sum(revenue) over (order by units, id rows between unbounded preceding and current row) as running_revenue from store_sales;
